const $=id=>document.getElementById(id), sources=window.PRINT_EVIDENCE.sources;
function cite(ids,access=false){return ids.map(id=>{const s=sources.find(s=>s.id===id);return `<a href="${s.url}">${s.title} ↗</a>${access?`<small>${s.access}</small>`:''}`}).join('');}
const views={
 whole:{title:'What belongs to the text?',copy:'The page preserves Greek and Latin alongside signs for navigating and assembling a book. Choose a layer: the enlargement and this margin will follow it.',aid:'A printed page records decisions. Its age alone does not tell us whether a reading is early.',label:'A useful distinction',limit:'The image is evidence. These labels and enlargements are modern reading aids.',x:50,y:50,scale:1,trail:'An object, then an argument',evidence:'This is printed page 183 of the Basel copy UBH BibG B 3. Its appearance is directly inspectable. Explaining why an editor chose a reading requires further evidence.',ids:['erasmus-page']},
 greek:{title:'Three witnesses in the Greek column',copy:'The list names spirit, water and blood. The heavenly witnesses clause does not precede it on this 1516 page. This is a printed editorial text, not a photograph of an ancient manuscript.',aid:'<p lang="grc">τὸ πνεῦμα, καὶ τὸ ὕδωρ καὶ τὸ αἷμα</p><p>the spirit, and the water and the blood</p>',label:'1 John 5:7–8 · short reading aid',limit:'Normalized Greek excerpt, abbreviations expanded. Literal study rendering; not a full verse or facsimile transcription.',x:19,y:45,scale:2.65,trail:'What this sheet can establish',evidence:'The absence of the Comma can be checked on this page. The later 1519 and 1522 states are reported through de Jonge. This object alone cannot establish Erasmus’s motives or the earliest form of 1 John.',ids:['erasmus-page','dejonge']},
 latin:{title:'A translation beside an edited text',copy:'Spiritus, aqua and sanguis correspond to spirit, water and blood. Erasmus’s Latin belongs to the same editorial undertaking as the Greek beside it.',aid:'Agreement across the columns does not provide two independent ancient manuscript votes.',label:'Translation ≠ independent attestation',limit:'Do not treat this Latin column as a second ancient source or assume that every polyglot column has the same function.',x:50,y:45,scale:2.65,trail:'Why the columns belong together',evidence:'The Basel exhibition presents Erasmus’s Latin work within his editorial project. A translation can reveal how an editor understood a Greek reading; it cannot automatically become independent evidence for that reading’s antiquity.',ids:['erasmus-page','basel-erasmus']},
 marks:{title:'Instructions for making a book',copy:'At the foot, q3 is a signature used when assembling gatherings. A catchword anticipates the following page’s text. These marks organize the physical book.',aid:'A printer’s mark can be essential to the book without belonging to the biblical text.',label:'Production, not translation',limit:'This enlargement preserves the actual page. It does not reconstruct the full gathering or attribute the handwritten note.',x:57,y:80,scale:2.65,trail:'From a sheet to an assembled volume',evidence:'The signature and catchword are visible at the foot of this sheet. The Plantin workshop record provides a separately sourced account of composition, correction and press work; it is not a photograph of Froben’s workshop.',ids:['erasmus-page','workshop']}
};
let state={view:'whole',year:1516,edition:'bhq',trail:false};
try{Object.assign(state,JSON.parse(sessionStorage.getItem('print-design')||'{}'));}catch{}
if(!views[state.view])state.view='whole';if(![1516,1519,1522].includes(state.year))state.year=1516;
const network=PRINT_EVIDENCE.networks[0];if(!['bh12','bh3','bhs','bhq'].includes(state.edition))state.edition='bhq';
function save(){try{sessionStorage.setItem('print-design',JSON.stringify(state));}catch{}}
function renderView(){const v=views[state.view];document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===state.view)));$('whole').setAttribute('aria-pressed',String(state.view==='whole'));$('folio').style.transform=`translate(${50-v.x}%,${50-v.y}%) scale(${v.scale})`;$('folio').style.transformOrigin=`${v.x}% ${v.y}%`;$('read-title').textContent=v.title;$('read-copy').textContent=v.copy;$('reading-aid').innerHTML=`<span class="small-label">${v.label}</span><p>${v.aid}</p>`;$('limit').textContent=v.limit;$('status').textContent=state.view==='whole'?'Look before interpreting':`Selected layer / ${state.view==='marks'?'Assembly marks':state.view}`;$('trail-title').textContent=v.trail;$('trail-copy').textContent=v.evidence;$('trail-sources').innerHTML=cite(v.ids,true);$('trail').hidden=!state.trail;$('trail-toggle').setAttribute('aria-expanded',String(state.trail));$('trail-toggle').textContent=state.trail?'Close the evidence trail ×':'Follow the evidence ↓';save();}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;renderView()});$('whole').onclick=()=>{state.view='whole';state.trail=false;renderView()};$('trail-toggle').onclick=()=>{state.trail=!state.trail;renderView()};function closeTrail(){state.trail=false;renderView();$('trail-toggle').focus({preventScroll:true});if($('trail-toggle').getBoundingClientRect().top<65)$('trail-toggle').scrollIntoView({block:'center'});}$('trail-close').onclick=closeTrail;document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.trail)closeTrail()});
function renderYear(){document.querySelectorAll('[data-year]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.year===state.year)));$('comma').textContent=state.year===1522?'Father · Word · Holy Spirit':'Not present in this Greek edition';$('year-limit').textContent=state.year===1516?'1516 · supported by the page above and de Jonge.':`${state.year} · state reported through de Jonge; not independently collated here.`;save();}document.querySelectorAll('[data-year]').forEach(b=>b.onclick=()=>{state.year=+b.dataset.year;renderYear()});$('revision-source').innerHTML=cite(['dejonge']);
function renderEdition(){const n=network.nodes.find(n=>n.id===state.edition);$('edition-title').textContent=n.label;$('edition-note').textContent=n.note;document.querySelectorAll('[data-edition]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.edition===state.edition)));document.querySelectorAll('[data-line]').forEach(p=>p.classList.toggle('active',p.dataset.line===state.edition));const edges=network.edges.filter(e=>e.to===state.edition);$('relationships').innerHTML=edges.map(e=>`<div><dt>${e.type==='text'?'Source of the main text':'Editorial succession'}</dt><dd>${network.nodes.find(n=>n.id===e.from).label} → ${n.label}<small>${e.label}</small>${cite(e.sourceIds)}</dd></div>`).join('');save();}document.querySelectorAll('[data-edition]').forEach(b=>b.onclick=()=>{state.edition=b.dataset.edition;renderEdition()});renderView();renderYear();renderEdition();
